zpl:
{#- ================= ASCEND TAG (designed 2.0" x 1" @ 203 dpi baseline) =================
   `s`  rescales vertical/font quantities by printer.dpi (label height stays fixed at 1").
   `hs` rescales horizontal quantities (x-positions, block widths, barcode max width) by
   the ACTUAL printed width vs. the 2.3" baseline this design was tuned at — so the layout
   compresses correctly whenever label.width is set to something other than 2.3" (e.g. 2.0"),
   not just when dpi changes.
   ^FT (not ^FO) anchors the shop name / code / price fields, matching the original .prn
   export — keep ^FT for those three specifically.
   ^FH\ remaps ZPL's hex-escape indicator from the default '_' to '\', so a literal
   underscore in the shop name/description/code isn't misread as a hex escape.

   ======================================================================================= -#}
{%- set shop_name = "Barrie's Ski and Sports" -%}

{%- set dpi = printer.dpi -%}
{%- set W = (label.width  * dpi) | int -%}
{%- set H = (label.height * dpi) | int -%}
{%- set s  = dpi / 203.0 -%}
{%- set hs = W / (2.3 * 203) -%}

{#- sanitize: ^ and ~ are ZPL control prefixes -#}
{%- set desc  = (doc.description or '') | replace('^',' ') | replace('~',' ') -%}
{#- barcode value: UPC, falling back to Store SKU (Store UPC) when UPC is blank -#}
{%- set code  = (doc.upc or doc.store_sku or '') | string | replace('^',' ') | replace('~',' ') -%}
{%- set price = '$' ~ ('%.2f' | format(doc.price | float)) -%}

{#- barcode geometry: Code 128, module width shrinks (down to 1) so the symbol fits
    max_width, then the bars are centered across W. No barcode is emitted without a
    UPC/Store SKU to encode. -#}
{%- set barcode_y = (94 * s) | int -%}
{%- set barcode_height = (46 * s) | int -%}
{%- set barcode_max_width = (420 * hs) | int -%}
{%- set barcode_zpl = '' -%}
{%- if code -%}
  {%- set modules = 11 * (code | length) + 35 -%}
  {%- set raw_module = barcode_max_width // modules -%}
  {%- set module = [1, [3, raw_module] | min] | max -%}
  {%- set bar_width = modules * module -%}
  {%- set barcode_x = [0, (W - bar_width) // 2] | max -%}
  {%- set barcode_zpl = '^BY' ~ module ~ ',2,' ~ barcode_height ~ '^FO' ~ barcode_x ~ ',' ~ barcode_y
       ~ '^BCN,' ~ barcode_height ~ ',N,N,N^FD' ~ code ~ '^FS' -%}
{%- endif -%}

^XA
^PW{{ W }}
^LL{{ H }}
^LS0
^LH0,0
^CI28
~SD15
^FT{{ (20*hs)|int }},{{ (36*s)|int }}^A0N,{{ (23*s)|int }},{{ (23*s)|int }}^FH\^FD{{ shop_name }}^FS
^FO{{ (16*hs)|int }},{{ (40*s)|int }}^A0N,{{ (24*s)|int }},{{ (24*s)|int }}^FB{{ (416*hs)|int }},2,2,L^FH\^FD{{ desc }}^FS
{{ barcode_zpl }}
^FT{{ (18*hs)|int }},{{ (191*s)|int }}^A0N,{{ (26*s)|int }},{{ (26*s)|int }}^FB{{ (224*hs)|int }},1,0,L^FH\^FD{{ code }}^FS
^FT{{ (248*hs)|int }},{{ (191*s)|int }}^A0N,{{ (37*s)|int }},{{ (38*s)|int }}^FB{{ (170*hs)|int }},1,0,R^FH\^FD{{ price }}^FS
^PQ{{ quantity }}
^XZ

{%- set dots = (label.width * printer.dpi) | int -%}
{%- set location = doc.name | replace('^', ' ') | replace('~', ' ') -%}
{%- set module_width = 2 -%}
{%- set barcode_width = (11 * (location | length) + 35) * module_width -%}
{%- set barcode_x = [(dots - barcode_width) // 2, 0] | max -%}
^XA
^PW{{ dots }}
^FO0,20^FB{{ dots }},1,0,C^A0N,30,30^FDBarrie's Warehouse^FS
^FO0,60^FB{{ dots }},1,0,C^A0N,40,40^FDLocation: {{ location }}^FS
^FO{{ barcode_x }},110^BY{{ module_width }}^BCN,80,N,N,N^FD{{ location }}^FS
^PQ{{ quantity }}
^XZ

{#- ================= SWAP TAG — rotated 90° clockwise =================
    Design is authored in the original portrait frame (width W, height H,
    stacked top→bottom via layout_state.current_y_position. Rotated rendering
    macros map each primitive 90° CW into the printed frame, where:
      printed width  = design height
      printed length = design width

      portrait (x, y) -> printed (H - y, x)

    Text is rendered using ^A0R.

    TUNING:
      Rotated ^FB/^GB/^BC anchoring varies slightly between Zebra firmware
      versions. If text prints clipped or mirrored, adjust:
        (1) render_rotated_text() origin Y
        (2) Orientation R ↔ B
===================================================================== -#}

{%- set dpi = printer.dpi -%}
{%- set label_design_width  = (label.width  * dpi) | int -%}
{%- set label_design_height = (label.height * dpi) | int -%}
{%- set dpi_scale_factor = dpi / 203.0 -%}

{#- -------------------------------------------------------------------
    Rendering macros
    Input coordinates are always portrait coordinates.
    Output coordinates are rotated 90° clockwise for printing.
-------------------------------------------------------------------- -#}

{%- macro render_rotated_text(
    current_y_position,
    font_height,
    text_content,
    maximum_lines=1
) -%}
^FO{{ label_design_height - current_y_position - font_height }},0
^FB{{ label_design_width }},{{ maximum_lines }},0,C
^A0R,{{ font_height }},{{ font_height }}
^FD{{ text_content }}^FS
{%- endmacro -%}

{%- macro render_rotated_rectangle(
    x_position,
    current_y_position,
    rectangle_width,
    rectangle_height,
    border_thickness
) -%}
^FO{{ label_design_height - current_y_position - rectangle_height }},{{ x_position }}
^GB{{ rectangle_height }},{{ rectangle_width }},{{ border_thickness }}^FS
{%- endmacro -%}

{#- -------------------------------------------------------------------
    Document values
-------------------------------------------------------------------- -#}

{%- set brand = (doc.brand or '')
    | replace('^',' ')
    | replace('~',' ')
-%}

{%- set model = (doc.style_name or '')
    | replace('^',' ')
    | replace('~',' ')
-%}

{%- set size = (doc.size or '')
    | replace('^',' ')
    | replace('~',' ')
-%}

{#- Barcode uses UPC, falling back to Store SKU if UPC is unavailable. -#}
{%- set barcode = (doc.upc or doc.store_sku or '')
    | replace('^',' ')
    | replace('~',' ')
-%}

{%- set formatted_swap_price =
    '$' ~ ('%.2f' | format(doc.swap_price | float))
-%}

{%- set formatted_msrp_price =
    '$' ~ ('%.2f' | format(doc.price | float))
-%}

{#- -------------------------------------------------------------------
    Font sizes (203 DPI baseline)
-------------------------------------------------------------------- -#}

{%- set header_font_height              = (26 * dpi_scale_factor) | int -%}
{%- set brand_font_height               = (54 * dpi_scale_factor) | int -%}
{%- set model_font_height               = (40 * dpi_scale_factor) | int -%}
{%- set size_font_height                = (50 * dpi_scale_factor) | int -%}
{%- set price_font_height               = (92 * dpi_scale_factor) | int -%}
{%- set msrp_font_height                = (32 * dpi_scale_factor) | int -%}
{%- set barcode_section_font_height     = (52 * dpi_scale_factor) | int -%}
{%- set barcode_price_font_height       = (38 * dpi_scale_factor) | int -%}
{%- set barcode_warning_font_height     = (26 * dpi_scale_factor) | int -%}
{%- set barcode_number_font_height      = (24 * dpi_scale_factor) | int -%}

{#- -------------------------------------------------------------------
    Barcode geometry (Code 128)
-------------------------------------------------------------------- -#}

{%- set barcode_module_width =
    (2 * dpi_scale_factor)
    | round(0, 'ceil')
    | int
-%}

{%- set barcode_height =
    (118 * dpi_scale_factor)
    | int
-%}

{%- set barcode_estimated_width =
    (11 * (barcode | length) + 35)
    * barcode_module_width
-%}

{%- set barcode_x_position =
    [(label_design_width - barcode_estimated_width) // 2, 0]
    | max
-%}

{#- -------------------------------------------------------------------
    Vertical layout cursor
-------------------------------------------------------------------- -#}

{%- set layout_state = namespace(
    current_y_position = (16 * dpi_scale_factor) | int
) -%}

^XA
^CI28
^PW{{ label_design_height }}
^LL{{ label_design_width }}
^LH0,0

{#- ===================== BRAND ===================== -#}

{{ render_rotated_text(
    layout_state.current_y_position,
    header_font_height,
    'BRAND:'
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((30 * dpi_scale_factor) | int)
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    brand_font_height,
    brand
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((62 * dpi_scale_factor) | int)
-%}

{#- ===================== MODEL ===================== -#}

{#- ---------------------------------------------------------------
    MODEL font fitting
---------------------------------------------------------------- #}

{%- set maximum_model_font_height = (40 * dpi_scale_factor) | int -%}
{%- set minimum_model_font_height = (24 * dpi_scale_factor) | int -%}

{%- set model_font_height = maximum_model_font_height -%}
{%- set estimated_model_width =
    (model | length) * model_font_height * 0.55
-%}

{%- if estimated_model_width > label_design_width - 20 -%}
    {%- set model_font_height =
        ((label_design_width - 20)
        / ((model | length) * 0.55))
        | int
    -%}
{%- endif -%}

{%- set model_maximum_lines = 1 -%}

{%- if model_font_height < minimum_model_font_height -%}
    {%- set model_font_height = minimum_model_font_height -%}
    {%- set model_maximum_lines = 2 -%}
{%- endif -%}

# END MODEL FONT FIT #

{{ render_rotated_text(
    layout_state.current_y_position,
    header_font_height,
    'MODEL:'
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((30 * dpi_scale_factor) | int)
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    model_font_height,
    model,
    model_maximum_lines
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position
    + (model_font_height * model_maximum_lines)
    + ((10 * dpi_scale_factor) | int)
-%}

{#- ===================== SIZE ===================== -#}

{{ render_rotated_text(
    layout_state.current_y_position,
    header_font_height,
    'SIZE:'
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((30 * dpi_scale_factor) | int)
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    size_font_height,
    size
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((58 * dpi_scale_factor) | int)
-%}

{#- ===================== PRICE ===================== -#}

{{ render_rotated_text(
    layout_state.current_y_position,
    header_font_height,
    'PRICE:'
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((32 * dpi_scale_factor) | int)
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    price_font_height,
    formatted_swap_price
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((100 * dpi_scale_factor) | int)
-%}

{#- ===================== MSRP ===================== -#}

{%- set msrp_display_text =
    'MSRP: ' ~ formatted_msrp_price
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    msrp_font_height,
    msrp_display_text
) }}

{%- set strikethrough_width =
    (0.55 * msrp_font_height * (msrp_display_text | length))
    | int
-%}

{%- set strikethrough_x_position =
    [(label_design_width - strikethrough_width) // 2, 0]
    | max
-%}

{%- set strikethrough_thickness =
    (4 * dpi_scale_factor)
    | round(0, 'ceil')
    | int
-%}

{{ render_rotated_rectangle(
    strikethrough_x_position,
    layout_state.current_y_position + (msrp_font_height // 2),
    strikethrough_width,
    strikethrough_thickness,
    strikethrough_thickness
) }}

{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((44 * dpi_scale_factor) | int)
-%}

{#- ===================== Separator ===================== -#}

{%- set separator_dash_length = (14 * dpi_scale_factor) | int -%}
{%- set separator_gap_length = (10 * dpi_scale_factor) | int -%}
{%- set separator_thickness =
    (4 * dpi_scale_factor)
    | round(0, 'ceil')
    | int
-%}
{%- set separator_margin = (18 * dpi_scale_factor) | int -%}

{%- for x_position in range(
    separator_margin,
    label_design_width - separator_margin,
    separator_dash_length + separator_gap_length
) -%}
{{ render_rotated_rectangle(
    x_position,
    layout_state.current_y_position,
    separator_dash_length,
    separator_thickness,
    separator_thickness
) }}
{%- endfor -%}

{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((26 * dpi_scale_factor) | int)
-%}

{#- ===================== Barcode Section ===================== -#}

{{ render_rotated_text(
    layout_state.current_y_position,
    barcode_section_font_height,
    'BAR'
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((58 * dpi_scale_factor) | int)
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    barcode_price_font_height,
    'Price: ' ~ formatted_swap_price
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((46 * dpi_scale_factor) | int)
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    barcode_warning_font_height,
    'DO NOT MARK ON BARCODE!'
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((32 * dpi_scale_factor) | int)
-%}

{{ render_rotated_text(
    layout_state.current_y_position,
    barcode_number_font_height,
    barcode
) }}
{%- set layout_state.current_y_position =
    layout_state.current_y_position + ((30 * dpi_scale_factor) | int)
-%}

^BY{{ barcode_module_width }}
^FO{{ label_design_height - layout_state.current_y_position - barcode_height }},{{ barcode_x_position }}
^BCR,{{ barcode_height }},N,N,N
^FD{{ barcode }}^FS

^PQ{{ quantity }}

^XZ
